#!/usr/bin/env python3
"""Regenerates the still-image fixtures and the capability probe's pictures.

Run on a Mac with Pillow installed (the HEIC files come from Apple's encoder
through sips, so they carry real irot/imir transforms and an Exif item):

    python3 test/fixtures/images/generate.py

Writes, beside this file: quadrants.{jpg,png,bmp,tiff,webp,gif} (192 x 96,
four colour quadrants red, green / blue, white, with sparse speckle so every
encoding clears the 1 KB floor), orientation-{1..8}.heic, orientation-6.
{png,webp,tiff}, alpha.png and display-p3.jpg; and src/core/
still-image-probe-fixtures.ts (one 24 x 16 picture per admitted format).
"""
import os, subprocess, sys
HERE = os.path.dirname(os.path.abspath(__file__))
os.chdir(HERE)
import io, base64
from PIL import Image, ImageDraw
W,H = 192,96
def quadrants():
    im = Image.new('RGB',(W,H))
    d = ImageDraw.Draw(im)
    hw,hh = W//2,H//2
    d.rectangle([0,0,hw-1,hh-1],fill=(255,0,0)); d.rectangle([hw,0,W-1,hh-1],fill=(0,255,0))
    d.rectangle([0,hh,hw-1,H-1],fill=(0,0,255)); d.rectangle([hw,hh,W-1,H-1],fill=(255,255,255))
    # Sparse deterministic speckle keeps every encoding above the 1 KB floor
    # and gives the encoders something to do; quadrant colours stay within +-10.
    import random
    rnd = random.Random(7)
    px = im.load()
    for _ in range(W*H//6):
        x,y = rnd.randrange(W), rnd.randrange(H)
        r,g,b = px[x,y]
        dv = rnd.choice((-10,10))
        px[x,y] = tuple(max(0,min(255,c+dv)) for c in (r,g,b))
    return im
q = quadrants()
q.save('quadrants.jpg', quality=92, subsampling=0)
q.save('quadrants.png'); q.save('quadrants.bmp'); q.save('quadrants.tiff', compression='tiff_lzw')
q.save('quadrants.webp', lossless=True)
q.convert('P', palette=Image.ADAPTIVE, colors=8).save('quadrants.gif')
# alpha: transparent surround, opaque red square
a = Image.new('RGBA',(128,128),(0,0,0,0))
ImageDraw.Draw(a).rectangle([32,32,95,95],fill=(255,0,0,255))
import random as _r
_g = _r.Random(3); _px = a.load()
for _ in range(900):
    x,y = _g.randrange(32,96), _g.randrange(32,96)
    _px[x,y] = (255, _g.randrange(0,30), 0, 255)
a.save('alpha.png')
# Display P3 swatch
p3 = open('/System/Library/ColorSync/Profiles/Display P3.icc','rb').read()
Image.new('RGB',(128,128),(180,90,40)).save('display-p3.jpg', icc_profile=p3, quality=95)
# one HEIC per EXIF orientation, written by Apple's encoder (irot/imir transforms)
for o in range(1,9):
    exif = Image.Exif(); exif[0x0112]=o
    q.save(f'/tmp/_o{o}.jpg', quality=95, subsampling=0, exif=exif)
    subprocess.run(['/usr/bin/sips','-s','format','heic',f'/tmp/_o{o}.jpg','--out',f'orientation-{o}.heic'],check=True,capture_output=True)
    os.remove(f'/tmp/_o{o}.jpg')

# EXIF orientation 6 carried by other containers
e6 = Image.Exif(); e6[0x0112]=6
q.save('orientation-6.png', exif=e6)
q.save('orientation-6.webp', lossless=True, exif=e6)
q.save('orientation-6.tiff', compression='tiff_lzw', exif=e6)


# --- the capability probe's pictures ---
W,H = 24,16
im = Image.new('RGB',(W,H),(40,120,200))
d = ImageDraw.Draw(im)
d.rectangle([0,0,11,7],fill=(220,40,40)); d.rectangle([12,8,23,15],fill=(240,240,240))
out = {}
def enc(fmt, **kw):
    b = io.BytesIO(); im.save(b, fmt, **kw); return b.getvalue()
out['jpeg'] = enc('JPEG', quality=80)
out['png'] = enc('PNG', optimize=True)
out['webp'] = enc('WEBP', lossless=True)
out['gif'] = io.BytesIO()
p = im.convert('P', palette=Image.ADAPTIVE, colors=4); b = io.BytesIO(); p.save(b,'GIF'); out['gif'] = b.getvalue()
out['tiff'] = enc('TIFF', compression='tiff_lzw')
b = io.BytesIO(); im.convert('P', palette=Image.ADAPTIVE, colors=4).save(b,'BMP'); out['bmp'] = b.getvalue()
# The HEIC probe picture is 128 x 96, not 24 x 16: libheif (1.23 at least)
# refuses a HEIC that small with "Security limit exceeded: Image size ...
# exceeds the maximum image size", even for a genuine Apple encode, so a tiny
# one would report HEIC as undecodable on a machine that reads real photos.
# 64 x 64 and 128 x 96 decode fine. Keep STILL_IMAGE_PROBE_SIZES in step.
big = Image.new('RGB',(128,96),(40,120,200))
bd = ImageDraw.Draw(big)
bd.rectangle([0,0,63,47],fill=(220,40,40)); bd.rectangle([64,48,127,95],fill=(240,240,240))
big.save('/tmp/_probe.jpg', quality=90)
subprocess.run(['/usr/bin/sips','-s','format','heic','/tmp/_probe.jpg','--out','/tmp/_probe.heic'],check=True,capture_output=True)
out['heic'] = open('/tmp/_probe.heic','rb').read()
lines = []
lines.append("""/**
 * One tiny real picture per admitted format (24 x 16 pixels, HEIC larger), for the
 * capability probe: preparing each one proves this machine can decode that
 * format, which a tool's presence on the search path does not. Generated by
 * test/fixtures/images/generate.py; the HEIC is written by Apple's encoder.
 * Each picture is a landscape of known shape, so a decoder that returns
 * something else has not decoded this.
 */

import type { StillImageFormat } from './still-image-formats.ts';

/**
 * The size each probe picture is. Every format but HEIC is 24 x 16. A HEIC
 * that small is refused by libheif's own security limit ("Image size exceeds
 * the maximum image size", seen on libheif 1.23 even for a genuine Apple
 * encode of 24 x 16), which would report HEIC as undecodable on a machine
 * that reads real photos; 64 x 64 and 128 x 96 decode fine, so the HEIC probe
 * picture is 128 x 96.
 */
export const STILL_IMAGE_PROBE_SIZES = {
  jpeg: { width: 24, height: 16 },
  png: { width: 24, height: 16 },
  heic: { width: 128, height: 96 },
  webp: { width: 24, height: 16 },
  gif: { width: 24, height: 16 },
  tiff: { width: 24, height: 16 },
  bmp: { width: 24, height: 16 },
} as const satisfies Readonly<Record<StillImageFormat, { width: number; height: number }>>;

export const STILL_IMAGE_PROBE_FIXTURES: Readonly<Record<StillImageFormat, string>> = {""")
for k in ['jpeg','png','heic','webp','gif','tiff','bmp']:
    lines.append(f"  {k}: '{base64.b64encode(out[k]).decode()}',")
lines.append("};\n")
open(os.path.join(HERE,'..','..','..','src','core','still-image-probe-fixtures.ts'),'w').write('\n'.join(lines))

